const GR_JA5A=[
 ["Two actions at once with ながら","Verb stem + ながら + verb","ながら (nagara) after a verb stem means that one person does two actions at the same time. The verb at the end is the main action. 聞きながら means “while listening”.",[["音楽","ongaku","music"],["を","o","(object)"],["聞きながら","kiki nagara","while listening"],["勉強します","benkyou shimasu","study"],["。","",""]],"I study while listening to music."],
 ["Probably with でしょう","A は B でしょう","Replace です with でしょう (deshou) to say that you think something is likely: “probably”. You are not sure. Do not use it for facts that you know.",[["あの","ano","that"],["店","mise","shop"],["は","wa","(topic)"],["高い","takai","expensive"],["でしょう","deshou","probably is"],["。","",""]],"That shop is probably expensive."],
 ["Advice with ほうがいいです","Verb た-form + ほうがいいです","The た-form of a verb plus ほうがいいです (hou ga ii desu) gives advice: “it is better to …”. 行ったほうがいいです means “it is better to go”.",[["医者","isha","doctor"],["に","ni","to"],["行った","itta","went (た-form)"],["ほうがいい","hou ga ii","it is better to"],["です","desu","is"],["。","",""]],"It is better to go to the doctor."],
 ["Advice not to with ないほうがいいです","Verb ない-form + ほうがいいです","The ない-form means “not do”. For る-verbs such as 食べる and 見る, take off る and add ない: 食べる becomes 食べない. For other verbs, change the last sound to the matching あ-row sound and add ない: 飲む becomes 飲まない, 行く becomes 行かない. Two verbs are irregular: する becomes しない and 来る becomes こない. Add ほうがいいです to say “it is better not to …”.",[["夜","yoru","night"],["は","wa","(topic)"],["コーヒー","koohii","coffee"],["を","o","(object)"],["飲まない","nomanai","do not drink"],["ほうがいい","hou ga ii","it is better to"],["です","desu","is"],["。","",""]],"It is better not to drink coffee at night."]
];
